/** Tick-box looks: an unchecked and a checked sprite (the extra checked ones are generated by scripts/make-ticks.mjs). */
export const TICK_STYLES = {
  classic: { off: 'raw/box_unchecked', on: 'raw/box_checked' },
  gold: { off: 'raw/box', on: 'raw/box_checked' },
  wood: { off: 'raw/box_wood', on: 'ticks/wood_on' },
  stone: { off: 'raw/box_stone_empty', on: 'ticks/stone_on' },
  barrel: { off: 'raw/box_wood_gold', on: 'ticks/barrel_on' },
  ember: { off: 'raw/bar_red_box', on: 'ticks/ember_on' },
  slot: { off: 'raw/box_large', on: 'raw/box_large_checked' },
} as const;
export type TickStyle = keyof typeof TICK_STYLES;
export const TICK_IDS = Object.keys(TICK_STYLES) as TickStyle[];
/** `id` may carry a colour variant (`wood~120`). */
export const tickDef = (id: string) => TICK_STYLES[id.split('~')[0] as TickStyle] ?? TICK_STYLES.classic;
export const tickHue = (id: string) => Number(id.split('~')[1]) || 0;
export const tickUrl = (path: string) => `url(/assets/${path}.png)`;
